#include <iostream>
#include <string>
#include <vector>

using namespace std;

/**
 * 題目 10437: Zeros and Ones
 * 給定一個長度達 1,000,000 的 0/1 字串。
 * 多次查詢 (i, j)，判斷索引 i 到 j (含) 之間的所有字元是否相同。
 * 
 * 優化思路：
 * 預處理字串，將連續相同的字元標記為同一個組號。
 * 查詢時只需判斷 group[i] 是否等於 group[j]。
 */

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    int caseNum = 1;
    while (cin >> s) {
        int n_queries;
        if (!(cin >> n_queries)) break;

        vector<int> group(s.length());
        int currentGroup = 0;
        group[0] = 0;
        for (int i = 1; i < (int)s.length(); ++i) {
            if (s[i] != s[i - 1]) currentGroup++;
            group[i] = currentGroup;
        }

        cout << "Case " << caseNum++ << ":" << endl;
        for (int k = 0; k < n_queries; ++k) {
            int i, j;
            cin >> i >> j;
            if (i >= (int)s.length() || j >= (int)s.length()) {
                cout << "No" << endl;
                continue;
            }
            if (group[i] == group[j]) {
                cout << "Yes" << endl;
            } else {
                cout << "No" << endl;
            }
        }
    }
    return 0;
}
